#include "ModuleGenerator.hpp"
#include "../Utils/FileWriter.hpp"
#include <filesystem>
namespace exotic { void ModuleGenerator::Generate(const std::string& name){ std::string root="Modules/"+name; std::filesystem::create_directories(root); FileWriter::Write(root+"/"+name+"Types.hpp","#pragma once\n\n////////////////////////////////////////////////////////////\n/// EXOTIC MODULE TYPES\n/// Module: "+name+"\n////////////////////////////////////////////////////////////\n\nnamespace exotic\n{\n\n//==========================================================\n// TYPES\n//==========================================================\n\nenum class "+name+"State\n{\n    Created,\n    Active,\n    Paused,\n    Error,\n    Destroyed\n};\n\n}\n"); FileWriter::Write(root+"/"+name+"Config.hpp","#pragma once\n#include ^<string^>\n\nnamespace exotic\n{\n\n//==========================================================\n// CONFIG\n//==========================================================\n\nstruct "+name+"Config\n{\n    std::string name = \""+name+"\";\n    bool enabled = true;\n};\n\n}\n"); FileWriter::Write(root+"/"+name+"Events.hpp","#pragma once\n#include ^<string^>\n\nnamespace exotic\n{\n\n//==========================================================\n// EVENTS\n//==========================================================\n\nstruct "+name+"Event\n{\n    std::string type;\n    std::string message;\n};\n\n}\n"); FileWriter::Write(root+"/"+name+"System.hpp","#pragma once\n#include \""+name+"Config.hpp\"\n#include \""+name+"Types.hpp\"\n\nnamespace exotic\n{\n\n//==========================================================\n// SYSTEM\n//==========================================================\n\nclass "+name+"System\n{\npublic:\n    void Initialize^(const "+name+"Config^& config^);\n    void Update^(^);\n    void Shutdown^(^);\n\nprivate:\n    "+name+"Config config;\n    "+name+"State state = "+name+"State::Created;\n};\n\n}\n"); FileWriter::Write(root+"/"+name+"System.cpp","#include \""+name+"System.hpp\"\n#include ^<iostream^>\n\nnamespace exotic\n{\n\n//==========================================================\n// LIFECYCLE\n//==========================================================\n\nvoid "+name+"System::Initialize^(const "+name+"Config^& cfg^)\n{\n    config = cfg;\n    state = "+name+"State::Active;\n    std::cout ^<^< \""+name+" system initialized.\" ^<^< std::endl;\n}\n\nvoid "+name+"System::Update^(^)\n{\n    if ^(state != "+name+"State::Active^) return;\n}\n\nvoid "+name+"System::Shutdown^(^)\n{\n    state = "+name+"State::Destroyed;\n}\n\n}\n"); FileWriter::Write(root+"/README.md","# "+name+" Module\n\nGenerated by Exotic Builder.\n\n## Structure\n\n- "+name+"Types.hpp\n- "+name+"Config.hpp\n- "+name+"Events.hpp\n- "+name+"System.hpp\n- "+name+"System.cpp\n\n## Purpose\n\nThis module follows the Exotic readable structure standard.\n"); } }
